### The Mission Capstone Firmware

Upload this complete, production-grade telemetry and watchdog sketch. Test it with your smartphone Bluetooth terminal app:
1. Send `'F'` to start driving.
2. Watch continuous telemetry stream onto your phone screen.
3. Turn off your phone's Bluetooth or walk into another room: within 2 seconds, the robot detects the signal timeout, halts the motors, and flashes the emergency alert LED!

```cpp
// Monster Lab - Capstone: Wireless Telemetry & Watchdog Failsafe
#include <SoftwareSerial.h>

// Virtual UART on Pins 10 (RX) and 11 (TX via voltage divider)
SoftwareSerial bt(10, 11);

const int MOTOR_PIN = 13;      // Simulates robot drive motor
const int TIMEOUT_MS = 2000;   // 2-second watchdog timeout deadline
const int TELEMETRY_MS = 1000; // 1-second telemetry broadcast period

unsigned long lastPacketTime = 0;
unsigned long lastTelemetryTime = 0;
unsigned long telemetrySequence = 0;

bool motorsRunning = false;
bool failsafeTriggered = false;

void setup() {
  Serial.begin(9600); // USB Debug Console
  bt.begin(9600);     // Wireless Bluetooth Link

  pinMode(MOTOR_PIN, OUTPUT);
  digitalWrite(MOTOR_PIN, LOW);

  Serial.println("========================================");
  Serial.println("CAPSTONE: ROBOT TELEMETRY & WATCHDOG ONLINE");
  Serial.println("========================================");

  lastPacketTime = millis(); // Initialize watchdog timer
}

void loop() {
  unsigned long currentMillis = millis();

  // -----------------------------------------------------
  // 1. INCOMING WIRELESS COMMAND PARSER
  // -----------------------------------------------------
  if (bt.available()) {
    char cmd = bt.read();

    if (cmd != '\r' && cmd != '\n') {
      // Any valid command or heartbeat resets the watchdog timer!
      lastPacketTime = currentMillis;

      if (failsafeTriggered) {
        failsafeTriggered = false;
        Serial.println("WATCHDOG: Connection restored by operator packet!");
        bt.println("EVENT: CONNECTION_RESTORED");
      }

      switch (cmd) {
        case 'F':
        case 'f':
          motorsRunning = true;
          digitalWrite(MOTOR_PIN, HIGH);
          bt.println("ACK: MOTORS_ENGAGED");
          break;

        case 'S':
        case 's':
          motorsRunning = false;
          digitalWrite(MOTOR_PIN, LOW);
          bt.println("ACK: MOTORS_STOPPED");
          break;

        case 'H':
        case 'h': // Heartbeat ping
          bt.println("ACK: HEARTBEAT_PONG");
          break;
      }
    }
  }

  // -----------------------------------------------------
  // 2. WATCHDOG CONNECTION TIMEOUT CHECK
  // -----------------------------------------------------
  if (!failsafeTriggered && (currentMillis - lastPacketTime > TIMEOUT_MS)) {
    failsafeTriggered = true;
    motorsRunning = false;
    digitalWrite(MOTOR_PIN, LOW); // EMERGENCY SHUTDOWN!

    Serial.println("ALARM: Wireless connection timed out! Emergency stop engaged.");
    bt.println("ALARM: WATCHDOG_TIMEOUT_EMERGENCY_HALT");
  }

  // -----------------------------------------------------
  // 3. PERIODIC DOWNLINK TELEMETRY BROADCAST (Every 1000ms)
  // -----------------------------------------------------
  if (currentMillis - lastTelemetryTime >= TELEMETRY_MS) {
    lastTelemetryTime = currentMillis;
    telemetrySequence++;

    // Read simulated rover telemetry
    int batteryLevel = 87; // Battery %
    int obstacleDist = 120; // Obstacle distance cm

    bt.print("$TLM,");
    bt.print(telemetrySequence);
    bt.print(",STATE:");
    bt.print(failsafeTriggered ? "FAILSAFE" : (motorsRunning ? "RUNNING" : "STOPPED"));
    bt.print(",BAT:");
    bt.print(batteryLevel);
    bt.print(",DIST:");
    bt.print(obstacleDist);
    bt.println("*END");
  }
}
```

### Code Breakdown:
1. **`lastPacketTime = currentMillis`:** Every valid command or heartbeat `'H'` resets the countdown timer.
2. **`currentMillis - lastPacketTime > TIMEOUT_MS`:** When silence exceeds 2000ms, the failsafe shuts down motors.
3. **Independent Periodic Telemetry:** Streams structured packets every 1000ms regardless of drive state.
